foreignObject.div:
-- PostgreSQL Relational Schema with Constraints and Indexes
CREATE TABLE departments (
    dept_id VARCHAR(10) PRIMARY KEY,
    dept_name VARCHAR(100) NOT NULL
);

CREATE TABLE students (
    student_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    usn VARCHAR(10) UNIQUE NOT NULL,
    full_name VARCHAR(120) NOT NULL,
    department_id VARCHAR(10) REFERENCES departments(dept_id) ON DELETE RESTRICT,
    current_semester INT CHECK (current_semester BETWEEN 1 AND 8),
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE courses (
    course_code VARCHAR(12) PRIMARY KEY,
    course_title VARCHAR(150) NOT NULL,
    credits INT CHECK (credits > 0),
    department_id VARCHAR(10) REFERENCES departments(dept_id)
);

CREATE TABLE marks_records (
    record_id BIGSERIAL PRIMARY KEY,
    student_id UUID NOT NULL REFERENCES students(student_id) ON DELETE CASCADE,
    course_code VARCHAR(12) NOT NULL REFERENCES courses(course_code),
    internal_score NUMERIC(5,2) CHECK (internal_score BETWEEN 0 AND 50),
    external_score NUMERIC(5,2) CHECK (external_score BETWEEN 0 AND 50),
    total_score NUMERIC(5,2) GENERATED ALWAYS AS (internal_score + external_score) STORED,
    grade_letter CHAR(2) NOT NULL
);

-- Compound index for rapid transcript retrieval
CREATE INDEX idx_student_transcript ON marks_records(student_id, course_code);
